                float bb = (float)0;
                for (int c = 0; c < n; c++) bb += B[j, c] * B[j, c];
                thr[j] = tol * tol * bb;
            }

            // R = B - A X.
            A.ApplyBlock(in X, ref Q, s);                 // Q = A X (temp use of Q)
            for (int i = 0; i < s; i++)
